type Variant = "primary" | "secondary" | "danger";
function buttonClass(variant: Variant): string { return `btn btn--${variant}`; }
console.log(buttonClass("danger")); // btn btn--danger

function idLabel(id: string | number): string { return `#${id}`; }
console.log(idLabel(42)); // #42
console.log(idLabel("tmp-1")); // #tmp-1

function describe(value: string | number): string {
  if (typeof value === "string") return value.trim();
  return value.toFixed(2);
}
console.log(describe(" API ")); // API
console.log(describe(3)); // 3.00

function assigneeLabel(assignee: string | null): string {
  if (assignee === null) return "Nieprzypisany";
  return assignee.toUpperCase();
}

function optionalTitle(title: string | undefined): string {
  if (title === undefined) return "Brak";
  return title;
}
console.log(optionalTitle(undefined)); // Brak
console.log(optionalTitle("").length); // 0

function truthy(value: string | null): string { return value ? value : "Brak"; }
function nullOnly(value: string | null): string { return value === null ? "Brak" : value; }
console.log(truthy("")); // Brak
console.log(nullOnly("").length); // 0

function tagsLabel(value: string | string[]): string {
  return Array.isArray(value) ? value.join(", ") : value;
}
console.log(tagsLabel(["api", "ui"])); // api, ui

type Owner = { login: string } | { teamName: string };
function ownerLabel(owner: Owner): string {
  if ("login" in owner) return owner.login;
  return owner.teamName;
}

function titleFromUnknown(value: unknown): string | null {
  if (typeof value !== "object" || value === null || !("title" in value)) return null;
  return typeof value.title === "string" ? value.title : null;
}

type LoadState = { status: "loading" } | { status: "error"; error: string } | { status: "success"; data: string[] };
const loading: LoadState = { status: "loading" };
const error: LoadState = { status: "error", error: "Brak sieci" };
const success: LoadState = { status: "success", data: ["API"] };

type LoadState = { status: "loading" } | { status: "error"; error: string } | { status: "success"; data: string[] };
function loadMessage(state: LoadState): string {
  if (state.status === "loading") return "Ładowanie";
  if (state.status === "error") return `Błąd: ${state.error}`;
  return `Pobrano: ${state.data.length}`;
}

type LoadState = { status: "loading" } | { status: "error"; error: string } | { status: "success"; data: string[] };
function loadedCount(state: LoadState): number | null {
  return state.status === "success" ? state.data.length : null;
}

type State = { status: "error"; error: string } | { status: "success"; data: string[] };
function typeCheckOnly(state: State) {
  if (state.status === "error") {
    // @ts-expect-error — ten wariant nie ma data
    return state.data;
  }
}

type State = { status: "idle" } | { status: "loading" } | { status: "error"; error: string } | { status: "success"; data: string[] };
function message(state: State): string {
  if (state.status === "idle") return "Gotowe do pobrania";
  if (state.status === "loading") return "Ładowanie";
  if (state.status === "error") return state.error;
  return `Wyniki: ${state.data.length}`;
}

type SaveResult = { status: "idle" } | { status: "saving" } | { status: "saved"; ticketId: number } | { status: "failed"; message: string };
function saveMessage(result: SaveResult): string {
  switch (result.status) {
    case "idle": return "Gotowe";
    case "saving": return "Zapisywanie";
    case "saved": return `Zapisano #${result.ticketId}`;
    case "failed": return result.message;
    default: { const unreachable: never = result; return unreachable; }
  }
}

type Result = { status: "saved"; id: number } | { status: "conflict"; message: string };
function typeCheckOnly(result: Result): string {
  switch (result.status) {
    case "saved": return String(result.id);
    default: {
      // @ts-expect-error — conflict nie zostało obsłużone
      const unreachable: never = result;
      return unreachable;
    }
  }
}

type Result = { status: "saved"; id: number } | { status: "conflict"; message: string };
function message(result: Result): string {
  switch (result.status) {
    case "saved": return String(result.id);
    case "conflict": return result.message;
    default: { const unreachable: never = result; return unreachable; }
  }
}

function assertNever(value: never): never { throw new Error(`Nieznany wariant: ${String(value)}`); }
type Status = "OPEN" | "CLOSED";
function statusLabel(status: Status): string {
  switch (status) {
    case "OPEN": return "Otwarty";
    case "CLOSED": return "Zamknięty";
    default: return assertNever(status);
  }
}

type Priority = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";
function priorityColor(priority: Priority): string {
  switch (priority) {
    case "LOW": return "gray";
    case "MEDIUM": return "blue";
    case "HIGH": return "orange";
    case "CRITICAL": return "red";
    default: { const unreachable: never = priority; return unreachable; }
  }
}

type Status = "OPEN" | "CLOSED";
type Filter = "ALL" | Status;
function matches(status: Status, filter: Filter): boolean { return filter === "ALL" || status === filter; }

type Action = { type: "select"; id: number } | { type: "clear" };
function selectedId(action: Action): number | null {
  if (action.type === "select") return action.id;
  return null;
}

function listLabel(value: unknown): string | null {
  if (!Array.isArray(value)) return null;
  const items: unknown[] = value;
  if (!items.every(item => typeof item === "string")) return null;
  return items.join(", ");
}
console.log(listLabel(["api", "ui"])); // api, ui
console.log(listLabel(["api", 42])); // null

type Result = { status: "error"; error: string } | { status: "success"; data: number[] };
function errorMessage(result: Result): string | null {
  if (result.status === "error") return result.error;
  return null;
}

function idLabel(id: number | null): string {
  if (id === null) return "Brak";
  return `#${id}`;
}
console.log(idLabel(0)); // #0

type SaveResult = { status: "idle" } | { status: "saving" } | { status: "saved"; ticketId: number } | { status: "failed"; message: string } | { status: "conflict"; message: string; currentVersion: number };
function saveMessage(result: SaveResult): string {
  switch (result.status) {
    case "idle": return "Gotowe";
    case "saving": return "Zapisywanie";
    case "saved": return `Zapisano #${result.ticketId}`;
    case "failed": return `Błąd: ${result.message}`;
    case "conflict": return `${result.message} (wersja ${result.currentVersion})`;
    default: { const unreachable: never = result; return unreachable; }
  }
}
console.log(saveMessage({ status: "idle" }));
console.log(saveMessage({ status: "saving" }));
console.log(saveMessage({ status: "saved", ticketId: 42 }));
console.log(saveMessage({ status: "failed", message: "Brak sieci" }));
console.log(saveMessage({ status: "conflict", message: "Zmienione dane", currentVersion: 2 }));

